import { Hono } from 'hono';
import { cors } from 'hono/cors';

interface Env {
  DB: D1Database; SESSIONS: KVNamespace; RATE_LIMIT: KVNamespace; ASSETS: Fetcher;
  APP_NAME: string; APP_URL: string; KORAPAY_BASE_URL: string; KORAPAY_SECRET_KEY: string;
  KORAPAY_PUBLIC_KEY: string; KORAPAY_WEBHOOK_SECRET: string; JWT_PRIVATE_KEY: string;
  JWT_PUBLIC_KEY: string; GOOGLE_CLIENT_ID: string; GOOGLE_CLIENT_SECRET: string; RESEND_API_KEY: string;
}
interface User {
  id: string; email: string; username: string | null; full_name: string | null; display_name: string | null;
  phone: string | null; country: string; currency: string; password_hash: string | null; email_verified: number;
  avatar_url: string | null; kyc_verified: number; kyc_verified_name: string | null; pin_hash: string | null;
  pin_attempts: number; pin_locked_until: number; biometrics_enabled: number; daily_limit: number;
  is_frozen: number; frozen_reason: string | null; frozen_at: string | null; created_at: string; updated_at: string;
}
interface JwtPayload { sub: string; email: string; username: string | null; exp: number; iat: number; }
const CURRENCIES = ['GHS','NGN','KES','USD','ZAR','UGX','TZS','RWF','GBP','CAD'] as const;
type Currency = typeof CURRENCIES[number];
const COUNTRIES = [{code:'GH',name:'Ghana',flag:'🇬🇭',currency:'GHS',symbol:'₵'},{code:'NG',name:'Nigeria',flag:'🇳🇬',currency:'NGN',symbol:'₦'},{code:'KE',name:'Kenya',flag:'🇰🇪',currency:'KES',symbol:'KSh'},{code:'ZA',name:'South Africa',flag:'🇿🇦',currency:'ZAR',symbol:'R'},{code:'UG',name:'Uganda',flag:'🇺🇬',currency:'UGX',symbol:'USh'},{code:'TZ',name:'Tanzania',flag:'🇹🇿',currency:'TZS',symbol:'TSh'},{code:'RW',name:'Rwanda',flag:'🇷🇼',currency:'RWF',symbol:'FRw'},{code:'US',name:'United States',flag:'🇺🇸',currency:'USD',symbol:'$'},{code:'GB',name:'United Kingdom',flag:'🇬🇧',currency:'GBP',symbol:'£'},{code:'CA',name:'Canada',flag:'🇨🇦',currency:'CAD',symbol:'C$'}];
const PAYMENT_CHANNELS = {visa:{name:'Visa',color:'#1A1F71'},mastercard:{name:'Mastercard',color:'#EB001B'},mtn_momo:{name:'MTN MoMo',color:'#FFCC00'},telecel_cash:{name:'Telecel Cash',color:'#E60000'},m_pesa:{name:'M-Pesa',color:'#41B549'},airtel_money:{name:'Airtel Money',color:'#E40000'}};
const MAX_PIN_ATTEMPTS=5,PIN_LOCKOUT_MS=30*60*1000,SESSION_TTL=7*24*60*60,JWT_TTL_MS=7*24*60*60*1000;
const TRANSFER_CHANNELS=['momo','ach','eft'] as const,PAYOUT_CHANNELS=['momo','ach','eft','card'] as const;
const MIN_AMOUNT=1,MAX_AMOUNT=10_000_000,FEE_PERCENT=0.015,FEE_MINIMUM=1.0,FEE_MAXIMUM=5000.0,MAX_BODY_SIZE=10*1024;
const app = new Hono<{ Bindings: Env }>();
app.use('*', async (c, next) => { const m = cors({origin:c.env.APP_URL||'*',allowMethods:['GET','POST','PUT','PATCH','DELETE','OPTIONS'],allowHeaders:['Content-Type','Authorization'],credentials:true}); await m(c, next); });
app.use('*', async (c, next) => { if (parseInt(c.req.header('Content-Length')||'0') > MAX_BODY_SIZE) return c.json({error:'Request body too large. Max 10KB.'},413); await next(); });
app.onError((err:any,c) => { console.error('Unhandled error:',err); return c.json({error:'An internal error occurred.'},500); });
app.notFound((c) => { if (c.req.path.startsWith('/api/')||c.req.path.startsWith('/v1/')) return c.json({error:'Endpoint not found'},404); return c.env.ASSETS.fetch(c.req.raw); });
function validateEmail(e:string):boolean { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e); }
function validatePin(p:string):boolean { return /^\d{4}$/.test(p); }
function validateAmount(a:any):number|null { const n=typeof a==='string'?parseFloat(a):a; if(typeof n!=='number'||!isFinite(n)||isNaN(n)||n<MIN_AMOUNT||n>MAX_AMOUNT) return null; return Math.round(n*100)/100; }
function validateCurrency(c:string):c is Currency { return (CURRENCIES as readonly string[]).includes(c); }
function sanitizeUsername(u:string):string { return u.toLowerCase().replace(/[^a-z0-9_]/g,''); }
function getClientIP(c:any):string { return c.req.header('CF-Connecting-IP')||c.req.header('X-Forwarded-For')?.split(',')[0]?.trim()||''; }
function calculateFee(a:number):number { return Math.round(Math.min(Math.max(a*FEE_PERCENT,FEE_MINIMUM),FEE_MAXIMUM)*100)/100; }
function validatePhone(p:string):boolean { return /^\+\d{8,15}$/.test(p); }
function generateToken(l=32):string { const a=new Uint8Array(l); crypto.getRandomValues(a); return Array.from(a).map(b=>b.toString(16).padStart(2,'0')).join(''); }
function generateId(p=''):string { return p+crypto.randomUUID(); }
function generateReference():string { return `MPL-${Date.now().toString(36)}-${Math.random().toString(36).substring(2,8)}`.toUpperCase(); }
function b64url(i:string|ArrayBuffer):string { if(typeof i==='string') return btoa(i).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,''); return btoa(String.fromCharCode(...new Uint8Array(i))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,''); }
function b64urlDecode(s:string):Uint8Array { return Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0)); }
async function hashPassword(p:string,s='mikpal_salt_v1'):Promise<string> { const d=new TextEncoder().encode(p+s); const h=await crypto.subtle.digest('SHA-256',d); return Array.from(new Uint8Array(h)).map(b=>b.toString(16).padStart(2,'0')).join(''); }
async function hashPin(p:string,s:string):Promise<string> { const d=new TextEncoder().encode(p+s+'pin_salt_v1'); const h=await crypto.subtle.digest('SHA-256',d); return Array.from(new Uint8Array(h)).map(b=>b.toString(16).padStart(2,'0')).join(''); }
async function importPrivateKey(j:any):Promise<CryptoKey> { return crypto.subtle.importKey('jwk',j,{name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'},false,['sign']); }
async function importPublicKey(j:any):Promise<CryptoKey> { return crypto.subtle.importKey('jwk',j,{name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'},false,['verify']); }
async function signJWT(p:Omit<JwtPayload,'iat'>,k:string):Promise<string> { const j=JSON.parse(k); const key=await importPrivateKey(j); const fp:JwtPayload={...p,iat:Date.now()}; const h={alg:'RS256',typ:'JWT',kid:j.kid||'MIKPAL-KEY-1'}; const d=`${b64url(JSON.stringify(h))}.${b64url(JSON.stringify(fp))}`; const s=await crypto.subtle.sign('RSASSA-PKCS1-v1_5',key,new TextEncoder().encode(d)); return `${d}.${b64url(s)}`; }
async function verifyJWT(t:string,k:string):Promise<JwtPayload|null> { try { const p=t.split('.'); if(p.length!==3) return null; const [h,pb,sb]=p; const d=`${h}.${pb}`; const key=await importPublicKey(JSON.parse(k)); const v=await crypto.subtle.verify('RSASSA-PKCS1-v1_5',key,b64urlDecode(sb),new TextEncoder().encode(d)); if(!v) return null; const pl:JwtPayload=JSON.parse(atob(pb.replace(/-/g,'+').replace(/_/g,'/'))); if(pl.exp&&Date.now()>pl.exp) return null; return pl; } catch { return null; } }
async function createNotification(env:Env,uid:string,type:string,title:string,msg:string,ref?:string,amt?:number,cur?:string):Promise<void> { await env.DB.prepare('INSERT INTO notifications (id,user_id,type,title,message,reference,amount,currency) VALUES (?,?,?,?,?,?,?,?)').bind(generateId('not_'),uid,type,title,msg,ref||null,amt||null,cur||null).run(); }
async function createSession(env:Env,uid:string,ip:string):Promise<string> { const t=generateToken(48); const th=await hashPassword(t); await env.SESSIONS.put(`session:${t}`,JSON.stringify({user_id:uid,expires_at:Date.now()+JWT_TTL_MS}),{expirationTtl:SESSION_TTL}); await env.DB.prepare('INSERT INTO sessions (id,user_id,token_hash,ip_address,expires_at) VALUES (?,?,?,?,?)').bind(generateId('ses_'),uid,th,ip,Date.now()+JWT_TTL_MS).run(); return t; }
async function verifySession(env:Env,t:string):Promise<{user_id:string}|null> { if(!t) return null; const kv=await env.SESSIONS.get(`session:${t}`); if(kv) { const p=JSON.parse(kv); if(Date.now()>p.expires_at) { await env.SESSIONS.delete(`session:${t}`); return null; } return {user_id:p.user_id}; } const th=await hashPassword(t); const s=await env.DB.prepare('SELECT user_id,expires_at FROM sessions WHERE token_hash=? AND expires_at>?').bind(th,Date.now()).first<any>(); if(!s) return null; await env.SESSIONS.put(`session:${t}`,JSON.stringify({user_id:s.user_id,expires_at:s.expires_at}),{expirationTtl:SESSION_TTL}); return {user_id:s.user_id}; }
async function destroySession(env:Env,t:string):Promise<void> { await env.SESSIONS.delete(`session:${t}`); const th=await hashPassword(t); await env.DB.prepare('DELETE FROM sessions WHERE token_hash=?').bind(th).run(); }
async function authMiddleware(c:any,next:any) { const ah=c.req.header('Authorization'); if(!ah||!ah.startsWith('Bearer ')) return c.json({error:'Unauthorized'},401); const t=ah.substring(7); let uid:string; const jp=await verifyJWT(t,c.env.JWT_PUBLIC_KEY); if(jp) uid=jp.sub; else { const s=await verifySession(c.env,t); if(!s) return c.json({error:'Invalid or expired session'},401); uid=s.user_id; } const u=await c.env.DB.prepare('SELECT id,email,username,is_frozen,frozen_reason FROM users WHERE id=?').bind(uid).first<any>(); if(!u) return c.json({error:'User not found'},401); if(u.is_frozen) return c.json({error:`Account frozen: ${u.frozen_reason||'Contact support'}`},403); c.set('user',{id:u.id,email:u.email,username:u.username}); await next(); }
async function checkRateLimit(env:Env,k:string,l:number,w:number):Promise<boolean> { const kk=`rl:${k}`; const c=await env.RATE_LIMIT.get(kk); const n=c?parseInt(c):0; if(n>=l) return false; await env.RATE_LIMIT.put(kk,String(n+1),{expirationTtl:w}); return true; }
async function audit(env:Env,uid:string|null,a:string,ip:string,d?:any):Promise<void> { await env.DB.prepare('INSERT INTO audit_log (id,user_id,action,ip_address,details) VALUES (?,?,?,?,?)').bind(generateId('aud_'),uid,a,ip,d?JSON.stringify(d):null).run(); }
async function sendEmail(env:Env,to:string,subject:string,html:string):Promise<boolean> { try { const r=await fetch('https://api.resend.com/emails',{method:'POST',headers:{'Authorization':`Bearer ${env.RESEND_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({from:'MIKPAL <noreply@mikpal.com>',to,subject,html})}); return r.ok; } catch { return false; } }
async function getOrCreateWallet(env:Env,uid:string,cur:string):Promise<{id:string,balance:number}> { let w=await env.DB.prepare('SELECT id,balance FROM wallets WHERE user_id=? AND currency=?').bind(uid,cur).first<any>(); if(!w) { const wid=generateId('wal_'); await env.DB.prepare('INSERT INTO wallets (id,user_id,currency,balance) VALUES (?,?,?,0.0)').bind(wid,uid,cur).run(); w={id:wid,balance:0.0}; } return w; }
async function getUserById(env:Env,uid:string):Promise<User|null> { return await env.DB.prepare('SELECT * FROM users WHERE id=?').bind(uid).first<User>(); }
async function getUserByUsername(env:Env,u:string):Promise<any> { return await env.DB.prepare('SELECT id,username,full_name,currency FROM users WHERE username=?').bind(u.toLowerCase()).first(); }
async function getWalletBalance(env:Env,uid:string,cur:string):Promise<{walletId:string,balance:number}|null> { const w=await env.DB.prepare('SELECT id,balance FROM wallets WHERE user_id=? AND currency=?').bind(uid,cur).first<any>(); if(!w) return null; return {walletId:w.id,balance:w.balance}; }
async function getTotalBalance(env:Env,uid:string):Promise<number> { const r=await env.DB.prepare('SELECT COALESCE(SUM(balance),0) as total FROM wallets WHERE user_id=?').bind(uid).first<any>(); return r?.total||0; }
async function getDailyOutgoingTotal(env:Env,uid:string):Promise<number> { const ts=new Date().toISOString().split('T')[0]+' 00:00:00'; const r=await env.DB.prepare("SELECT COALESCE(SUM(amount+fee),0) as total FROM transactions WHERE user_id=? AND status='success' AND type IN ('transfer','payout','p2p_send') AND created_at>=?").bind(uid,ts).first<any>(); return r?.total||0; }
async function verifyPinForTransaction(env:Env,uid:string,pin:string):Promise<{valid:boolean,error?:string}> { const u=await getUserById(env,uid); if(!u) return {valid:false,error:'User not found'}; if(u.pin_locked_until&&u.pin_locked_until>Date.now()) { const m=Math.ceil((u.pin_locked_until-Date.now())/60000); return {valid:false,error:`PIN locked. Try again in ${m} minutes.`}; } if(!u.pin_hash) return {valid:false,error:'No PIN set. Please set a 4-digit PIN first.'}; const ph=await hashPin(pin,uid); if(ph!==u.pin_hash) { const na=u.pin_attempts+1; if(na>=MAX_PIN_ATTEMPTS) { await env.DB.prepare('UPDATE users SET pin_attempts=0,pin_locked_until=? WHERE id=?').bind(Date.now()+PIN_LOCKOUT_MS,uid).run(); return {valid:false,error:'Too many failed attempts. PIN locked for 30 minutes.'}; } await env.DB.prepare('UPDATE users SET pin_attempts=? WHERE id=?').bind(na,uid).run(); return {valid:false,error:`Incorrect PIN. ${MAX_PIN_ATTEMPTS-na} attempts remaining.`}; } if(u.pin_attempts>0) await env.DB.prepare('UPDATE users SET pin_attempts=0 WHERE id=?').bind(uid).run(); return {valid:true}; }
async function validateOutgoingTransaction(env:Env,uid:string,amt:number,fee:number):Promise<{ok:boolean,error?:string}> { const u=await getUserById(env,uid); if(!u) return {ok:false,error:'User not found'}; if(!u.kyc_verified) return {ok:false,error:'KYC verification is required before sending money. Please complete KYC in your profile.'}; const dt=await getDailyOutgoingTotal(env,uid); if(dt+amt+fee>u.daily_limit) { const r=Math.max(0,u.daily_limit-dt); return {ok:false,error:`Daily transaction limit is ${u.daily_limit.toFixed(2)}. You have ${r.toFixed(2)} remaining today.`}; } return {ok:true}; }
async function safeUserWithBalance(env:Env,u:User) { const b=await getTotalBalance(env,u.id); return {id:u.id,email:u.email,username:u.username,full_name:u.full_name,display_name:u.display_name,phone:u.phone,country:u.country,currency:u.currency,email_verified:!!u.email_verified,avatar_url:u.avatar_url,kyc_verified:!!u.kyc_verified,kyc_verified_name:u.kyc_verified_name,has_pin:!!u.pin_hash,biometrics_enabled:!!u.biometrics_enabled,balance:b,daily_limit:u.daily_limit,is_frozen:!!u.is_frozen,created_at:u.created_at}; }
function safeUser(u:User) { return {id:u.id,email:u.email,username:u.username,full_name:u.full_name,display_name:u.display_name,phone:u.phone,country:u.country,currency:u.currency,email_verified:!!u.email_verified,avatar_url:u.avatar_url,kyc_verified:!!u.kyc_verified,kyc_verified_name:u.kyc_verified_name,has_pin:!!u.pin_hash,biometrics_enabled:!!u.biometrics_enabled,daily_limit:u.daily_limit,is_frozen:!!u.is_frozen,created_at:u.created_at}; }
app.post('/api/auth/signup', async (c) => { const ip=getClientIP(c); if(!(await checkRateLimit(c.env,`signup:${ip}`,5,3600))) return c.json({error:'Too many signup attempts.'},429); const {email,password,full_name,username,phone,country}=await c.req.json(); if(!email||!password||!full_name) return c.json({error:'Email, password, and full name are required'},400); if(!validateEmail(email)) return c.json({error:'Invalid email'},400); if(password.length<8) return c.json({error:'Password must be 8+ chars'},400); const el=email.toLowerCase(); const ex=await c.env.DB.prepare('SELECT id FROM users WHERE email=?').bind(el).first(); if(ex) return c.json({error:'Account exists'},409); let fu:string|null=null; if(username) { fu=sanitizeUsername(username); if(fu.length<3) return c.json({error:'Username 3+ chars'},400); const eu=await c.env.DB.prepare('SELECT id FROM users WHERE username=?').bind(fu).first(); if(eu) return c.json({error:'Username taken'},409); } const uid=generateId('usr_'); const ph=await hashPassword(password); const uc=country||'Ghana'; const ucur=(COUNTRIES.find(co=>co.name===uc)||COUNTRIES[0]).currency; await c.env.DB.batch([c.env.DB.prepare('INSERT INTO users (id,email,username,password_hash,full_name,phone,country,currency,email_verified) VALUES (?,?,?,?,?,?,?,?,0)').bind(uid,el,fu,ph,full_name,phone||null,uc,ucur),c.env.DB.prepare('INSERT INTO wallets (id,user_id,currency,balance) VALUES (?,?,?,0.0)').bind(generateId('wal_'),uid,ucur)]); const vt=generateToken(32); await c.env.DB.prepare('INSERT INTO auth_tokens (id,user_id,token,type,expires_at) VALUES (?,?,?,?,?)').bind(generateId('tok_'),uid,vt,'email_verify',Date.now()+86400000).run(); const vu=`${c.env.APP_URL}/verify-email?token=${vt}`; await sendEmail(c.env,el,'Verify your MIKPAL account',`<h2>Welcome!</h2><p>Verify: <a href="${vu}">Click here</a></p>`); const t=await createSession(c.env,uid,ip); const jwt=await signJWT({sub:uid,email:el,username:fu,exp:Date.now()+JWT_TTL_MS},c.env.JWT_PRIVATE_KEY); const u=await getUserById(c.env,uid); await audit(c.env,uid,'signup',ip); return c.json({user:safeUser(u!),token:jwt,sessionToken:t,emailVerificationRequired:true},201); });
app.post('/api/auth/signin', async (c) => { const ip=getClientIP(c); if(!(await checkRateLimit(c.env,`signin:${ip}`,10,3600))) return c.json({error:'Too many login attempts.'},429); const {email,password}=await c.req.json(); if(!email||!password) return c.json({error:'Email and password required'},400); const ph=await hashPassword(password); const u=await c.env.DB.prepare('SELECT * FROM users WHERE email=? AND password_hash=?').bind(email.toLowerCase(),ph).first<User>(); if(!u) return c.json({error:'Invalid email or password'},401); const t=await createSession(c.env,u.id,ip); const jwt=await signJWT({sub:u.id,email:u.email,username:u.username,exp:Date.now()+JWT_TTL_MS},c.env.JWT_PRIVATE_KEY); await audit(c.env,u.id,'login',ip); return c.json({user:safeUser(u),token:jwt,sessionToken:t}); });
app.post('/api/auth/google', async (c) => { const ip=getClientIP(c); const {credential}=await c.req.json(); if(!credential) return c.json({error:'Google credential required'},400); const gr=await fetch(`https://oauth2.googleapis.com/tokeninfo?id_token=${credential}`); if(!gr.ok) return c.json({error:'Invalid Google token'},401); const gu:any=await gr.json(); if(gu.aud!==c.env.GOOGLE_CLIENT_ID) return c.json({error:'Google token mismatch'},401); let oa=await c.env.DB.prepare("SELECT user_id FROM oauth_accounts WHERE provider='google' AND provider_account_id=?").bind(gu.sub).first<any>(); let uid:string; let u:User|null; if(oa) { uid=oa.user_id; u=await getUserById(c.env,uid); } else { u=await c.env.DB.prepare('SELECT * FROM users WHERE email=?').bind(gu.email).first<User>(); if(u) { uid=u.id; } else { uid=generateId('usr_'); const un=gu.email.split('@')[0]+'_'+generateToken(4); await c.env.DB.batch([c.env.DB.prepare('INSERT INTO users (id,email,username,email_verified,avatar_url,currency) VALUES (?,?,?,?,1,?,?)').bind(uid,gu.email,un,gu.picture||null,'GHS'),c.env.DB.prepare('INSERT INTO wallets (id,user_id,currency,balance) VALUES (?,?,?,0.0)').bind(generateId('wal_'),uid,'GHS')]); u=await getUserById(c.env,uid); } await c.env.DB.prepare("INSERT INTO oauth_accounts (id,user_id,provider,provider_account_id) VALUES (?,?,'google',?)").bind(generateId('oau_'),uid,gu.sub).run(); } const t=await createSession(c.env,uid,ip); const jwt=await signJWT({sub:uid,email:u!.email,username:u!.username,exp:Date.now()+JWT_TTL_MS},c.env.JWT_PRIVATE_KEY); await audit(c.env,uid,'google_login',ip); return c.json({user:safeUser(u!),token:jwt,sessionToken:t}); });
app.post('/api/auth/verify-email', async (c) => { const {token}=await c.req.json(); if(!token) return c.json({error:'Token required'},400); const at=await c.env.DB.prepare("SELECT * FROM auth_tokens WHERE token=? AND type='email_verify' AND used=0 AND expires_at>?").bind(token,Date.now()).first<any>(); if(!at) return c.json({error:'Invalid or expired token'},400); await c.env.DB.batch([c.env.DB.prepare('UPDATE users SET email_verified=1 WHERE id=?').bind(at.user_id),c.env.DB.prepare('UPDATE auth_tokens SET used=1 WHERE id=?').bind(at.id)]); return c.json({success:true,message:'Email verified'}); });
app.post('/api/auth/forgot-password', async (c) => { const ip=getClientIP(c); if(!(await checkRateLimit(c.env,`forgot:${ip}`,3,3600))) return c.json({error:'Too many attempts.'},429); const {email}=await c.req.json(); if(!email) return c.json({error:'Email required'},400); const u=await c.env.DB.prepare('SELECT id FROM users WHERE email=?').bind(email.toLowerCase()).first<any>(); if(!u) return c.json({success:true,message:'If email exists, link sent'}); const rt=generateToken(32); await c.env.DB.prepare("INSERT INTO auth_tokens (id,user_id,token,type,expires_at) VALUES (?,?,'password_reset',?)").bind(generateId('tok_'),u.id,Date.now()+3600000).run(); await sendEmail(c.env,email,'Reset password',`<p>Reset: <a href="${c.env.APP_URL}/reset-password?token=${rt}">Click here</a></p>`); await audit(c.env,u.id,'password_reset_request',ip); return c.json({success:true,message:'If email exists, link sent'}); });
app.post('/api/auth/reset-password', async (c) => { const {token,password}=await c.req.json(); if(!token||!password) return c.json({error:'Token and password required'},400); if(password.length<8) return c.json({error:'Password 8+ chars'},400); const at=await c.env.DB.prepare("SELECT * FROM auth_tokens WHERE token=? AND type='password_reset' AND used=0 AND expires_at>?").bind(token,Date.now()).first<any>(); if(!at) return c.json({error:'Invalid token'},400); const ph=await hashPassword(password); await c.env.DB.batch([c.env.DB.prepare("UPDATE users SET password_hash=?,updated_at=datetime('now') WHERE id=?").bind(ph,at.user_id),c.env.DB.prepare('UPDATE auth_tokens SET used=1 WHERE id=?').bind(at.id)]); await audit(c.env,at.user_id,'password_reset',getClientIP(c)); return c.json({success:true,message:'Password reset'}); });
app.get('/api/auth/me', authMiddleware, async (c) => { const u=c.get('user'); const du=await getUserById(c.env,u.id); if(!du) return c.json({error:'Not found'},404); return c.json({user:await safeUserWithBalance(c.env,du)}); });
app.post('/api/auth/signout', authMiddleware, async (c) => { const u=c.get('user'); const ah=c.req.header('Authorization'); const t=ah?.substring(7)||''; await destroySession(c.env,t); await audit(c.env,u.id,'logout',getClientIP(c)); return c.json({success:true}); });
app.get('/api/profile', authMiddleware, async (c) => { const u=c.get('user'); const du=await getUserById(c.env,u.id); if(!du) return c.json({error:'Not found'},404); return c.json({user:await safeUserWithBalance(c.env,du)}); });
app.put('/api/profile', authMiddleware, async (c) => { const u=c.get('user'); const {display_name,currency,phone,country,username}=await c.req.json(); if(currency&&!validateCurrency(currency)) return c.json({error:'Invalid currency'},400); if(username) { const cu=sanitizeUsername(username); if(cu.length<3) return c.json({error:'Username 3+ chars'},400); const ex=await c.env.DB.prepare('SELECT id FROM users WHERE username=? AND id!=?').bind(cu,u.id).first(); if(ex) return c.json({error:'Username taken'},409); } const up:string[]=[]; const v:any[]=[]; if(display_name!==undefined){up.push('display_name=?');v.push(display_name);} if(currency){up.push('currency=?');v.push(currency);} if(phone!==undefined){up.push('phone=?');v.push(phone);} if(country){up.push('country=?');v.push(country);} if(username){up.push('username=?');v.push(sanitizeUsername(username));} up.push("updated_at=datetime('now')"); if(v.length>0){v.push(u.id);await c.env.DB.prepare(`UPDATE users SET ${up.join(', ')} WHERE id=?`).bind(...v).run();} const uu=await getUserById(c.env,u.id); return c.json({user:await safeUserWithBalance(c.env,uu!)}); });
app.put('/api/profile/password', authMiddleware, async (c) => { const u=c.get('user'); const {current_password,new_password}=await c.req.json(); if(!current_password||!new_password) return c.json({error:'Both required'},400); if(new_password.length<8) return c.json({error:'8+ chars'},400); const ch=await hashPassword(current_password); const du=await c.env.DB.prepare('SELECT password_hash FROM users WHERE id=?').bind(u.id).first<any>(); if(du.password_hash!==ch) return c.json({error:'Wrong password'},401); const nh=await hashPassword(new_password); await c.env.DB.prepare("UPDATE users SET password_hash=?,updated_at=datetime('now') WHERE id=?").bind(nh,u.id).run(); await audit(c.env,u.id,'password_change',getClientIP(c)); return c.json({message:'Password updated'}); });
app.put('/api/profile/pin', authMiddleware, async (c) => { const u=c.get('user'); const {current_pin,new_pin}=await c.req.json(); if(!new_pin||!validatePin(new_pin)) return c.json({error:'PIN must be 4 digits'},400); const du=await getUserById(c.env,u.id); if(du!.pin_hash) { if(!current_pin) return c.json({error:'Current PIN required'},400); const cph=await hashPin(current_pin,u.id); if(cph!==du!.pin_hash) return c.json({error:'Wrong PIN'},401); } const nph=await hashPin(new_pin,u.id); await c.env.DB.prepare("UPDATE users SET pin_hash=?,pin_attempts=0,pin_locked_until=0,updated_at=datetime('now') WHERE id=?").bind(nph,u.id).run(); await audit(c.env,u.id,'pin_change',getClientIP(c)); return c.json({message:'PIN updated'}); });
app.post('/api/profile/pin/verify', authMiddleware, async (c) => { const u=c.get('user'); const {pin}=await c.req.json(); if(!pin||!validatePin(pin)) return c.json({error:'PIN 4 digits'},400); const r=await verifyPinForTransaction(c.env,u.id,pin); if(!r.valid) return c.json({error:r.error},401); return c.json({verified:true}); });
app.put('/api/profile/biometrics', authMiddleware, async (c) => { const u=c.get('user'); const {enabled}=await c.req.json(); await c.env.DB.prepare("UPDATE users SET biometrics_enabled=?,updated_at=datetime('now') WHERE id=?").bind(enabled?1:0,u.id).run(); return c.json({biometrics_enabled:!!enabled}); });
app.post('/api/profile/kyc', authMiddleware, async (c) => { const u=c.get('user'); const {document_type,document_number,full_name}=await c.req.json(); if(!document_type||!document_number) return c.json({error:'Document required'},400); const du=await getUserById(c.env,u.id); const vn=full_name||du!.full_name||''; await c.env.DB.batch([c.env.DB.prepare("UPDATE users SET kyc_verified=1,kyc_verified_name=?,kyc_document_type=?,kyc_document_number=?,full_name=?,updated_at=datetime('now') WHERE id=?").bind(vn,document_type,document_number,vn,u.id),c.env.DB.prepare("INSERT INTO kyc_verifications (id,user_id,status,document_type,document_number,verified_at) VALUES (?,?,'verified',?,?,datetime('now'))").bind(generateId('kyc_'),u.id,document_type,document_number)]); await audit(c.env,u.id,'kyc_submit',getClientIP(c),{document_type}); return c.json({message:'KYC verified',kyc_verified:true,verified_name:vn}); });
app.get('/api/dashboard', authMiddleware, async (c) => { const u=c.get('user'); const du=await getUserById(c.env,u.id); if(!du) return c.json({error:'Not found'},404); const tb=await getTotalBalance(c.env,u.id); const rt=await c.env.DB.prepare('SELECT id,type,channel,amount,fee,currency,status,reference,description,created_at FROM transactions WHERE user_id=? ORDER BY created_at DESC LIMIT 10').bind(u.id).all(); const va=await c.env.DB.prepare('SELECT COUNT(*) as count FROM virtual_accounts WHERE user_id=? AND is_active=1').bind(u.id).first<any>(); const cc=await c.env.DB.prepare('SELECT COUNT(*) as count FROM cards WHERE user_id=? AND is_active=1').bind(u.id).first<any>(); const ws=await c.env.DB.prepare('SELECT id,currency,balance FROM wallets WHERE user_id=? ORDER BY currency').bind(u.id).all(); const ci=COUNTRIES.find(co=>co.currency===du.currency)||COUNTRIES[0]; return c.json({user:{id:du.id,email:du.email,username:du.username,full_name:du.full_name,display_name:du.display_name,kyc_verified:!!du.kyc_verified,kyc_verified_name:du.kyc_verified_name,country:du.country,currency:du.currency,currency_symbol:ci.symbol,country_flag:ci.flag,balance:tb,daily_limit:du.daily_limit},wallets:ws.results||[],recent_transactions:rt.results||[],virtual_accounts_count:va?.count||0,cards_count:cc?.count||0,payment_channels:PAYMENT_CHANNELS,supported_countries:COUNTRIES}); });
app.get('/api/wallets', authMiddleware, async (c) => { const u=c.get('user'); const ws=await c.env.DB.prepare('SELECT id,currency,balance,locked_balance FROM wallets WHERE user_id=? ORDER BY currency').bind(u.id).all(); return c.json({wallets:ws.results||[]}); });
app.post('/api/wallets', authMiddleware, async (c) => { const u=c.get('user'); const {currency}=await c.req.json(); if(!currency||!validateCurrency(currency)) return c.json({error:'Invalid currency'},400); const w=await getOrCreateWallet(c.env,u.id,currency); return c.json({wallet:w}); });
app.get('/api/transactions', authMiddleware, async (c) => { const u=c.get('user'); const l=Math.min(parseInt(c.req.query('limit')||'20'),100); const o=parseInt(c.req.query('offset')||'0'); const r=await c.env.DB.prepare('SELECT * FROM transactions WHERE user_id=? ORDER BY created_at DESC LIMIT ? OFFSET ?').bind(u.id,l,o).all(); return c.json({transactions:r.results||[],count:r.results?.length||0}); });
app.get('/api/transactions/:id', authMiddleware, async (c) => { const u=c.get('user'); const id=c.req.param('id'); const t=await c.env.DB.prepare('SELECT * FROM transactions WHERE id=? AND user_id=?').bind(id,u.id).first(); if(!t) return c.json({error:'Not found'},404); return c.json({transaction:t}); });
app.post('/api/transactions/transfer', authMiddleware, async (c) => { const u=c.get('user'); const ip=getClientIP(c); const {pin,channel,amount,currency,recipient_name,recipient_account,recipient_bank,description,idempotency_key}=await c.req.json(); if(!channel||!(TRANSFER_CHANNELS as readonly string[]).includes(channel)) return c.json({error:'Invalid channel'},400); const amt=validateAmount(amount); if(amt===null) return c.json({error:'Invalid amount'},400); const pc=await verifyPinForTransaction(c.env,u.id,pin); if(!pc.valid) return c.json({error:pc.error},401); const fee=calculateFee(amt); const td=amt+fee; const v=await validateOutgoingTransaction(c.env,u.id,amt,fee); if(!v.ok) return c.json({error:v.error},403); if(idempotency_key) { const ex=await c.env.DB.prepare('SELECT id,reference,status FROM transactions WHERE idempotency_key=?').bind(idempotency_key).first<any>(); if(ex) return c.json({message:'Already processed',reference:ex.reference,idempotent:true}); } const du=await getUserById(c.env,u.id); if(!du) return c.json({error:'Not found'},404); const tc=currency||du.currency; if(!validateCurrency(tc)) return c.json({error:'Invalid currency'},400); const wi=await getWalletBalance(c.env,u.id,tc); if(!wi) return c.json({error:`No ${tc} wallet`},400); if(wi.balance<td) return c.json({error:`Insufficient. Need ${td.toFixed(2)}, have ${wi.balance.toFixed(2)}`},400); const txId=generateId('tx_'); const ref=generateReference(); await c.env.DB.prepare("INSERT INTO transactions (id,user_id,type,channel,amount,fee,currency,status,reference,description,recipient_name,recipient_account,recipient_bank,pin_verified,idempotency_key) VALUES (?,?,'transfer',?,?,?,?,?,?,'pending',?,?,?,?,1,?)").bind(txId,u.id,channel,amt,fee,tc,ref,description||`Transfer via ${channel.toUpperCase()}`,recipient_name,recipient_account,recipient_bank,idempotency_key||null).run(); const dr=await c.env.DB.prepare("UPDATE wallets SET balance=balance-?,updated_at=datetime('now') WHERE id=? AND balance>=?").bind(td,wi.walletId,td).run(); if(!dr.meta.changes||dr.meta.changes===0) { await c.env.DB.prepare("UPDATE transactions SET status='failed',updated_at=datetime('now') WHERE id=?").bind(txId).run(); return c.json({error:'Insufficient at execution time'},409); } try { const kr=await fetch(`${c.env.KORAPAY_BASE_URL}/merchant/api/v1/disbursements/card`,{method:'POST',headers:{'Authorization':`Bearer ${c.env.KORAPAY_SECRET_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({reference:ref,amount:amt*100,currency:tc,customer:{name:recipient_name,email:du.email},destination:{type:channel,account_number:recipient_account,bank_code:recipient_bank}})}); const kd:any=await kr.json(); if(!kr.ok) { await c.env.DB.batch([c.env.DB.prepare("UPDATE wallets SET balance=balance+?,updated_at=datetime('now') WHERE id=?").bind(td,wi.walletId),c.env.DB.prepare("UPDATE transactions SET status='failed',updated_at=datetime('now') WHERE id=?").bind(txId)]); await audit(c.env,u.id,'transfer_failed',ip,{txId,ref,error:kd}); return c.json({error:'Transfer failed at provider',details:kd?.message||'Unknown'},502); } await c.env.DB.prepare("UPDATE transactions SET status='success',updated_at=datetime('now') WHERE id=?").bind(txId).run(); await c.env.DB.prepare("INSERT INTO gateway_transactions (reference,user_id,amount,currency,payment_method,provider,provider_reference,status) VALUES (?,?,?,?,?,'korapay',?,'success')").bind(ref,u.id,amt,tc,channel,kd?.data?.reference||null).run(); const nb=await getWalletBalance(c.env,u.id,tc); await audit(c.env,u.id,'transfer',ip,{txId,ref,amount:amt,fee,currency:tc,channel}); await createNotification(c.env,u.id,'transfer_sent','Transfer Sent',`Transfer of ${amt.toFixed(2)} ${tc} via ${channel.toUpperCase()} successful. Ref: ${ref}`,ref,amt,tc); await sendEmail(c.env,du.email,'Transfer successful',`<h2>Transfer ${amt.toFixed(2)} ${tc}</h2><p>Ref: ${ref}</p>`); return c.json({message:'Transfer successful',transaction_id:txId,reference:ref,amount:amt,fee,currency:tc,new_balance:nb?.balance??0,status:'success'}); } catch(err:any) { await c.env.DB.batch([c.env.DB.prepare("UPDATE wallets SET balance=balance+?,updated_at=datetime('now') WHERE id=?").bind(td,wi.walletId),c.env.DB.prepare("UPDATE transactions SET status='failed',updated_at=datetime('now') WHERE id=?").bind(txId)]); await audit(c.env,u.id,'transfer_error',ip,{txId,ref,error:err.message}); await createNotification(c.env,u.id,'transfer_failed','Transfer Failed',`Transfer of ${amt.toFixed(2)} ${tc} failed. Refunded. Ref: ${ref}`,ref,amt,tc); return c.json({error:'Provider error. Refunded.',details:err.message},502); } });
app.post('/api/transactions/payout', authMiddleware, async (c) => { const u=c.get('user'); const ip=getClientIP(c); const {pin,channel,amount,currency,recipient_name,recipient_account,recipient_bank,description,idempotency_key}=await c.req.json(); if(!channel||!(PAYOUT_CHANNELS as readonly string[]).includes(channel)) return c.json({error:'Invalid channel'},400); const amt=validateAmount(amount); if(amt===null) return c.json({error:'Invalid amount'},400); const pc=await verifyPinForTransaction(c.env,u.id,pin); if(!pc.valid) return c.json({error:pc.error},401); const fee=calculateFee(amt); const td=amt+fee; const v=await validateOutgoingTransaction(c.env,u.id,amt,fee); if(!v.ok) return c.json({error:v.error},403); if(idempotency_key) { const ex=await c.env.DB.prepare('SELECT id,reference,status FROM transactions WHERE idempotency_key=?').bind(idempotency_key).first<any>(); if(ex) return c.json({message:'Already processed',reference:ex.reference,idempotent:true}); } const du=await getUserById(c.env,u.id); if(!du) return c.json({error:'Not found'},404); const tc=currency||du.currency; if(!validateCurrency(tc)) return c.json({error:'Invalid currency'},400); const wi=await getWalletBalance(c.env,u.id,tc); if(!wi) return c.json({error:`No ${tc} wallet`},400); if(wi.balance<td) return c.json({error:`Insufficient. Need ${td.toFixed(2)}, have ${wi.balance.toFixed(2)}`},400); const txId=generateId('tx_'); const ref=generateReference(); await c.env.DB.prepare("INSERT INTO transactions (id,user_id,type,channel,amount,fee,currency,status,reference,description,recipient_name,recipient_account,recipient_bank,pin_verified,idempotency_key) VALUES (?,?,'payout',?,?,?,?,?,?,'pending',?,?,?,?,1,?)").bind(txId,u.id,channel,amt,fee,tc,ref,description||`Payout via ${channel.toUpperCase()}`,recipient_name,recipient_account,recipient_bank,idempotency_key||null).run(); const dr=await c.env.DB.prepare("UPDATE wallets SET balance=balance-?,updated_at=datetime('now') WHERE id=? AND balance>=?").bind(td,wi.walletId,td).run(); if(!dr.meta.changes||dr.meta.changes===0) { await c.env.DB.prepare("UPDATE transactions SET status='failed',updated_at=datetime('now') WHERE id=?").bind(txId).run(); return c.json({error:'Insufficient at execution time'},409); } try { const kr=await fetch(`${c.env.KORAPAY_BASE_URL}/merchant/api/v1/disbursements/card`,{method:'POST',headers:{'Authorization':`Bearer ${c.env.KORAPAY_SECRET_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({reference:ref,amount:amt*100,currency:tc,customer:{name:recipient_name,email:du.email},destination:{type:channel,account_number:recipient_account,bank_code:recipient_bank}})}); const kd:any=await kr.json(); if(!kr.ok) { await c.env.DB.batch([c.env.DB.prepare("UPDATE wallets SET balance=balance+?,updated_at=datetime('now') WHERE id=?").bind(td,wi.walletId),c.env.DB.prepare("UPDATE transactions SET status='failed',updated_at=datetime('now') WHERE id=?").bind(txId)]); await audit(c.env,u.id,'payout_failed',ip,{txId,ref,error:kd}); return c.json({error:'Payout failed at provider',details:kd?.message||'Unknown'},502); } await c.env.DB.prepare("UPDATE transactions SET status='success',updated_at=datetime('now') WHERE id=?").bind(txId).run(); await c.env.DB.prepare("INSERT INTO gateway_transactions (reference,user_id,amount,currency,payment_method,provider,provider_reference,status) VALUES (?,?,?,?,?,'korapay',?,'success')").bind(ref,u.id,amt,tc,channel,kd?.data?.reference||null).run(); const nb=await getWalletBalance(c.env,u.id,tc); await audit(c.env,u.id,'payout',ip,{txId,ref,amount:amt,fee,currency:tc,channel}); await createNotification(c.env,u.id,'payout_sent','Payout Sent',`Payout of ${amt.toFixed(2)} ${tc} via ${channel.toUpperCase()} successful. Ref: ${ref}`,ref,amt,tc); await sendEmail(c.env,du.email,'Payout successful',`<h2>Payout ${amt.toFixed(2)} ${tc}</h2><p>Ref: ${ref}</p>`); return c.json({message:'Payout successful',transaction_id:txId,reference:ref,amount:amt,fee,currency:tc,new_balance:nb?.balance??0,status:'success'}); } catch(err:any) { await c.env.DB.batch([c.env.DB.prepare("UPDATE wallets SET balance=balance+?,updated_at=datetime('now') WHERE id=?").bind(td,wi.walletId),c.env.DB.prepare("UPDATE transactions SET status='failed',updated_at=datetime('now') WHERE id=?").bind(txId)]); await audit(c.env,u.id,'payout_error',ip,{txId,ref,error:err.message}); await createNotification(c.env,u.id,'payout_failed','Payout Failed',`Payout of ${amt.toFixed(2)} ${tc} failed. Refunded. Ref: ${ref}`,ref,amt,tc); return c.json({error:'Provider error. Refunded.',details:err.message},502); } });
app.post('/api/p2p/lookup', authMiddleware, async (c) => { const {username}=await c.req.json(); if(!username) return c.json({error:'Username required'},400); const cu=sanitizeUsername(username); const s=c.get('user'); const su=await getUserById(c.env,s.id); if(su?.username===cu) return c.json({error:'Cannot send to yourself'},400); const r=await getUserByUsername(c.env,cu); if(!r) return c.json({error:'User not found'},404); return c.json({recipient:{username:r.username,full_name:r.full_name,currency:r.currency}}); });
app.post('/api/p2p/transfer', authMiddleware, async (c) => { const s=c.get('user'); const ip=getClientIP(c); const {pin,recipient_username,amount,currency,description,idempotency_key}=await c.req.json(); const pc=await verifyPinForTransaction(c.env,s.id,pin); if(!pc.valid) return c.json({error:pc.error},401); const amt=validateAmount(amount); if(amt===null) return c.json({error:'Invalid amount'},400); const fee=calculateFee(amt); const td=amt+fee; const v=await validateOutgoingTransaction(c.env,s.id,amt,fee); if(!v.ok) return c.json({error:v.error},403); const cu=sanitizeUsername(recipient_username||''); if(!cu) return c.json({error:'Recipient required'},400); const r=await getUserByUsername(c.env,cu); if(!r) return c.json({error:'Recipient not found'},404); if(r.id===s.id) return c.json({error:'Cannot send to yourself'},400); const su=await getUserById(c.env,s.id); const tc=currency||su!.currency; if(!validateCurrency(tc)) return c.json({error:'Invalid currency'},400); if(r.currency!==tc) return c.json({error:`Currency mismatch. Recipient uses ${r.currency}`},400); if(idempotency_key) { const ex=await c.env.DB.prepare('SELECT id,reference FROM ledger_entries WHERE idempotency_key=?').bind(idempotency_key).first<any>(); if(ex) return c.json({message:'Already processed',reference:ex.reference,idempotent:true}); } const swi=await getWalletBalance(c.env,s.id,tc); if(!swi) return c.json({error:`No ${tc} wallet`},400); if(swi.balance<td) return c.json({error:`Insufficient. Need ${td.toFixed(2)}, have ${swi.balance.toFixed(2)}`},400); const rw=await getOrCreateWallet(c.env,r.id,tc); const lid=generateId('led_'); const ref=generateReference(); const stx=generateId('tx_'); const rtx=generateId('tx_'); const ftx=generateId('tx_'); const dr=await c.env.DB.prepare("UPDATE wallets SET balance=balance-?,updated_at=datetime('now') WHERE id=? AND balance>=?").bind(td,swi.walletId,td).run(); if(!dr.meta.changes||dr.meta.changes===0) return c.json({error:'Insufficient at execution time'},409); await c.env.DB.batch([c.env.DB.prepare("UPDATE wallets SET balance=balance+?,updated_at=datetime('now') WHERE id=?").bind(amt,rw.id),c.env.DB.prepare("INSERT INTO ledger_entries (id,sender_id,recipient_id,amount,fee,currency,status,reference,idempotency_key,pin_verified,note) VALUES (?,?,?,?,?,?,'success',?,?,1,?)").bind(lid,s.id,r.id,amt,fee,tc,ref,idempotency_key||null,description||null),c.env.DB.prepare("INSERT INTO transactions (id,user_id,type,channel,amount,fee,currency,status,reference,description,recipient_name,pin_verified,idempotency_key) VALUES (?,?,'p2p_send','p2p',?,?,?,'success',?,?,?,1,?)").bind(stx,s.id,amt,fee,tc,ref,description||`P2P to @${r.username}`,`@${r.username}`,idempotency_key||null),c.env.DB.prepare("INSERT INTO transactions (id,user_id,type,channel,amount,fee,currency,status,reference,description,recipient_name,pin_verified) VALUES (?,?,'p2p_receive','p2p',?,0.0,?,'success',?,?,0)").bind(rtx,r.id,amt,tc,ref,`P2P from @${su!.username||su!.email}`,`@${su!.username||su!.email}`),c.env.DB.prepare("INSERT INTO transactions (id,user_id,type,channel,amount,fee,currency,status,reference,description,pin_verified) VALUES (?,?,'fee','system',?,0.0,?,'success',?,'Transaction fee',1)").bind(ftx,s.id,fee,tc,ref)]); await audit(c.env,s.id,'p2p_transfer',ip,{ref,amount:amt,fee,currency:tc,recipient:r.username}); await createNotification(c.env,r.id,'p2p_received','Money Received',`Received ${amt.toFixed(2)} ${tc} from @${su!.username||su!.email}`,ref,amt,tc); await sendEmail(c.env,r.email||'','Money received',`<h2>Received ${amt.toFixed(2)} ${tc}</h2><p>From: @${su!.username||su!.email}</p><p>Ref: ${ref}</p>`); const nb=await getWalletBalance(c.env,s.id,tc); return c.json({message:'P2P successful',reference:ref,transaction_id:stx,amount:amt,fee,currency:tc,recipient:{username:r.username,full_name:r.full_name},new_balance:nb?.balance??0,status:'success'}); });
app.get('/api/p2p/history', authMiddleware, async (c) => { const u=c.get('user'); const l=Math.min(parseInt(c.req.query('limit')||'20'),100); const o=parseInt(c.req.query('offset')||'0'); const r=await c.env.DB.prepare("SELECT le.*,s.username as su,s.full_name as sn,r.username as ru,r.full_name as rn FROM ledger_entries le JOIN users s ON le.sender_id=s.id JOIN users r ON le.recipient_id=r.id WHERE le.sender_id=? OR le.recipient_id=? ORDER BY le.created_at DESC LIMIT ? OFFSET ?").bind(u.id,u.id,l,o).all(); return c.json({transfers:r.results||[],count:r.results?.length||0}); });
app.post('/api/deposit/initiate', authMiddleware, async (c) => { const u=c.get('user'); const {amount,currency,paymentMethod}=await c.req.json(); const amt=validateAmount(amount); if(amt===null) return c.json({error:'Invalid amount'},400); if(!currency||!validateCurrency(currency)) return c.json({error:'Invalid currency'},400); if(!paymentMethod) return c.json({error:'Payment method required'},400); const ref=`MIK_${generateToken(12)}`; const du=await getUserById(c.env,u.id); await c.env.DB.prepare("INSERT INTO gateway_transactions (reference,user_id,amount,currency,payment_method,status) VALUES (?,?,?,?,?,'pending')").bind(ref,u.id,amt,currency,paymentMethod).run(); try { const kr=await fetch(`${c.env.KORAPAY_BASE_URL}/merchant/api/v1/charge/initialize`,{method:'POST',headers:{'Authorization':`Bearer ${c.env.KORAPAY_SECRET_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({reference:ref,amount:amt*100,currency,customer:{email:du!.email},channels:[paymentMethod],redirect_url:`${c.env.APP_URL}/deposit/callback?reference=${ref}`})}); const kd:any=await kr.json(); if(!kr.ok) { await c.env.DB.prepare("UPDATE gateway_transactions SET status='failed' WHERE reference=?").bind(ref).run(); return c.json({error:'Init failed',details:kd},400); } return c.json({reference:ref,paymentUrl:kd?.data?.checkout_url,message:'Deposit initiated'}); } catch(err:any) { await c.env.DB.prepare("UPDATE gateway_transactions SET status='failed' WHERE reference=?").bind(ref).run(); return c.json({error:'Provider error',details:err.message},502); } });
app.get('/api/deposit/verify/:reference', authMiddleware, async (c) => { const u=c.get('user'); const ref=c.req.param('reference'); if(!ref) return c.json({error:'Reference required'},400); const gt=await c.env.DB.prepare('SELECT status,user_id,amount,currency FROM gateway_transactions WHERE reference=? AND user_id=?').bind(ref,u.id).first<any>(); if(!gt) return c.json({error:'Not found'},404); if(gt.status==='success') return c.json({status:'success',reference:ref,message:'Already processed'}); if(gt.status==='failed') return c.json({status:'failed',reference:ref,message:'Failed'}); try { const kr=await fetch(`${c.env.KORAPAY_BASE_URL}/merchant/api/v1/charge/${ref}`,{method:'GET',headers:{'Authorization':`Bearer ${c.env.KORAPAY_SECRET_KEY}`}}); if(!kr.ok) return c.json({status:'pending',reference:ref,message:'Could not verify'}); const kd:any=await kr.json(); const cs=kd?.data?.status||kd?.status; if(cs==='success') { const amt=validateAmount(gt.amount); if(amt===null) return c.json({error:'Invalid amount'},400); const w=await getOrCreateWallet(c.env,u.id,gt.currency); await c.env.DB.batch([c.env.DB.prepare("UPDATE gateway_transactions SET status='success',updated_at=datetime('now') WHERE reference=?").bind(ref),c.env.DB.prepare("UPDATE wallets SET balance=balance+?,updated_at=datetime('now') WHERE id=?").bind(amt,w.id),c.env.DB.prepare("INSERT INTO transactions (id,user_id,type,channel,amount,fee,currency,status,reference,description,webhook_reference) VALUES (?,?,'deposit','korapay',?,0.0,?,'success',?,'Korapay deposit (verified)',?)").bind(generateId('tx_'),u.id,amt,gt.currency,ref,ref)]); await createNotification(c.env,u.id,'deposit','Deposit Verified',`Deposit of ${amt.toFixed(2)} ${gt.currency} verified. Ref: ${ref}`,ref,amt,gt.currency); const nb=await getWalletBalance(c.env,u.id,gt.currency); return c.json({status:'success',reference:ref,amount:amt,currency:gt.currency,new_balance:nb?.balance??0}); } else if(cs==='failed') { await c.env.DB.prepare("UPDATE gateway_transactions SET status='failed',updated_at=datetime('now') WHERE reference=?").bind(ref).run(); return c.json({status:'failed',reference:ref,message:'Failed at provider'}); } return c.json({status:'pending',reference:ref,message:'Still pending'}); } catch { return c.json({status:'pending',reference:ref,message:'Try again later'}); } });
async function handleKorapayWebhook(c:any) { const rawBody=await c.req.text(); let body:any; try { body=JSON.parse(rawBody); } catch { return c.json({error:'Invalid JSON'},400); } const sig=c.req.header('x-korapay-signature')||c.req.header('X-Korapay-Signature')||''; if(c.env.KORAPAY_WEBHOOK_SECRET) { const enc=new TextEncoder(); const key=await crypto.subtle.importKey('raw',enc.encode(c.env.KORAPAY_WEBHOOK_SECRET),{name:'HMAC',hash:'SHA-256'},false,['sign']); const sigBuf=await crypto.subtle.sign('HMAC',key,enc.encode(rawBody)); const es=btoa(String.fromCharCode(...new Uint8Array(sigBuf))); if(sig!==es) return c.json({error:'Invalid signature'},401); } const {event,data}=body; const ref=data?.reference||data?.tx_ref; if(!ref) return c.json({error:'No reference'},400); const ex=await c.env.DB.prepare('SELECT id,processed FROM webhook_events WHERE reference=?').bind(ref).first<any>(); if(ex) return c.json({success:true,message:'Already processed'}); await c.env.DB.prepare("INSERT INTO webhook_events (id,event_type,reference,processed,payload) VALUES (?,?,?,0,?)").bind(generateId('wh_'),event,ref,rawBody).run(); if(event==='charge.success') { const tx=await c.env.DB.prepare('SELECT user_id,amount,currency FROM gateway_transactions WHERE reference=?').bind(ref).first<any>(); if(tx) { const amt=validateAmount(tx.amount); if(amt===null) return c.json({error:'Invalid amount'},400); const w=await getOrCreateWallet(c.env,tx.user_id,tx.currency); await c.env.DB.batch([c.env.DB.prepare("UPDATE gateway_transactions SET status='success',updated_at=datetime('now') WHERE reference=?").bind(ref),c.env.DB.prepare("UPDATE wallets SET balance=balance+?,updated_at=datetime('now') WHERE id=?").bind(amt,w.id),c.env.DB.prepare("INSERT INTO transactions (id,user_id,type,channel,amount,fee,currency,status,reference,description,webhook_reference) VALUES (?,?,'deposit','korapay',?,0.0,?,'success',?,'Korapay deposit',?)").bind(generateId('tx_'),tx.user_id,amt,tx.currency,ref,ref),c.env.DB.prepare("UPDATE webhook_events SET processed=1 WHERE reference=?").bind(ref),c.env.DB.prepare("INSERT INTO audit_log (id,user_id,action,details) VALUES (?,?,'deposit',?)").bind(generateId('aud_'),tx.user_id,JSON.stringify({ref,amount:amt,currency:tx.currency}))]); const du=await getUserById(c.env,tx.user_id); if(du) { await createNotification(c.env,tx.user_id,'deposit','Deposit Successful',`Deposit of ${amt.toFixed(2)} ${tx.currency} successful. Ref: ${ref}`,ref,amt,tx.currency); await sendEmail(c.env,du.email,'Deposit successful',`<h2>Deposit ${amt.toFixed(2)} ${tx.currency}</h2><p>Ref: ${ref}</p>`); } return c.json({success:true,message:'Deposit processed',reference:ref,amount:amt,currency:tx.currency}); } } else if(event==='charge.failed') { await c.env.DB.prepare("UPDATE gateway_transactions SET status='failed',updated_at=datetime('now') WHERE reference=?").bind(ref).run(); await c.env.DB.prepare("UPDATE webhook_events SET processed=1 WHERE reference=?").bind(ref).run(); return c.json({success:true,message:'Failure recorded'}); } else if(event==='disbursement.success'||event==='payout.success') { const tx=await c.env.DB.prepare("SELECT id,user_id,amount,fee,currency,status,type FROM transactions WHERE reference=? AND type IN ('payout','transfer')").bind(ref).first<any>(); if(tx&&tx.status==='pending') { await c.env.DB.prepare("UPDATE transactions SET status='success',updated_at=datetime('now') WHERE id=?").bind(tx.id).run(); await c.env.DB.prepare("UPDATE gateway_transactions SET status='success',updated_at=datetime('now') WHERE reference=?").bind(ref).run(); await createNotification(c.env,tx.user_id,tx.type==='payout'?'payout_sent':'transfer_sent',`${tx.type==='payout'?'Payout':'Transfer'} Confirmed`,`Your ${tx.type} of ${tx.amount.toFixed(2)} ${tx.currency} confirmed. Ref: ${ref}`,ref,tx.amount,tx.currency); } await c.env.DB.prepare("UPDATE webhook_events SET processed=1 WHERE reference=?").bind(ref).run(); return c.json({success:true,message:'Disbursement success',reference:ref}); } else if(event==='disbursement.failed'||event==='payout.failed') { const tx=await c.env.DB.prepare("SELECT id,user_id,amount,fee,currency,status,type FROM transactions WHERE reference=? AND type IN ('payout','transfer')").bind(ref).first<any>(); if(tx&&(tx.status==='success'||tx.status==='pending')) { const td=tx.amount+tx.fee; const wi=await getWalletBalance(c.env,tx.user_id,tx.currency); if(wi) { await c.env.DB.batch([c.env.DB.prepare("UPDATE wallets SET balance=balance+?,updated_at=datetime('now') WHERE id=?").bind(td,wi.walletId),c.env.DB.prepare("UPDATE transactions SET status=?,updated_at=datetime('now') WHERE id=?").bind(tx.status==='success'?'reversed':'failed',tx.id),c.env.DB.prepare("UPDATE gateway_transactions SET status='failed',updated_at=datetime('now') WHERE reference=?").bind(ref)]); await createNotification(c.env,tx.user_id,tx.type==='payout'?'payout_failed':'transfer_failed',`${tx.type==='payout'?'Payout':'Transfer'} Failed — Refunded`,`${tx.type} of ${tx.amount.toFixed(2)} ${tx.currency} failed. ${td.toFixed(2)} refunded. Ref: ${ref}`,ref,tx.amount,tx.currency); const fu=await getUserById(c.env,tx.user_id); if(fu) await sendEmail(c.env,fu.email,`${tx.type} failed`,`<h2>Failed</h2><p>Refunded: ${td.toFixed(2)}</p>`); await audit(c.env,tx.user_id,`${tx.type}_reversed`,'',{ref,amount:tx.amount,refunded:td}); } } await c.env.DB.prepare("UPDATE webhook_events SET processed=1 WHERE reference=?").bind(ref).run(); return c.json({success:true,message:'Disbursement failure — refunded',reference:ref}); } await c.env.DB.prepare("UPDATE webhook_events SET processed=1 WHERE reference=?").bind(ref).run(); return c.json({success:true,message:`Event ${event} received`}); }
app.post('/api/webhooks/korapay', async (c) => { return handleKorapayWebhook(c); });
app.post('/v1/webhooks/korapay', async (c) => { return handleKorapayWebhook(c); });
app.get('/api/virtual-accounts', authMiddleware, async (c) => { const u=c.get('user'); const r=await c.env.DB.prepare('SELECT * FROM virtual_accounts WHERE user_id=? AND is_active=1 ORDER BY created_at DESC').bind(u.id).all(); return c.json({accounts:r.results||[]}); });
app.post('/api/virtual-accounts', authMiddleware, async (c) => { const u=c.get('user'); const du=await getUserById(c.env,u.id); if(!du) return c.json({error:'Not found'},404); const bn='Providus Bank'; const an=(du.full_name||du.email).toUpperCase(); const anum=String(Math.floor(8000000000+Math.random()*999999999)); const rn='021000021'; const sc='PVBNGNGL'; const aid=generateId('va_'); await c.env.DB.prepare('INSERT INTO virtual_accounts (id,user_id,bank_name,account_name,account_number,routing_number,swift_code,provider) VALUES (?,?,?,?,?,?,?,?)').bind(aid,u.id,bn,an,anum,rn,sc,'kora').run(); await audit(c.env,u.id,'virtual_account_create',getClientIP(c)); return c.json({message:'Virtual account created',account:{id:aid,bank_name:bn,account_name:an,account_number:anum,routing_number:rn,swift_code:sc}},201); });
app.get('/api/cards', authMiddleware, async (c) => { const u=c.get('user'); const r=await c.env.DB.prepare('SELECT id,card_type,last4,expiry_month,expiry_year,cardholder_name,is_active,created_at FROM cards WHERE user_id=? AND is_active=1 ORDER BY created_at DESC').bind(u.id).all(); return c.json({cards:r.results||[]}); });
app.post('/api/cards', authMiddleware, async (c) => { const u=c.get('user'); const {card_type,last4,expiry_month,expiry_year,cardholder_name}=await c.req.json(); if(!card_type||!last4) return c.json({error:'Card type and last4 required'},400); if(!['visa','mastercard','virtual'].includes(card_type)) return c.json({error:'Invalid type'},400); if(!/^\d{4}$/.test(last4)) return c.json({error:'Last4 must be 4 digits'},400); const cid=generateId('card_'); await c.env.DB.prepare('INSERT INTO cards (id,user_id,card_type,last4,expiry_month,expiry_year,cardholder_name) VALUES (?,?,?,?,?,?,?)').bind(cid,u.id,card_type,last4,expiry_month,expiry_year,cardholder_name).run(); return c.json({message:'Card added',card_id:cid},201); });
app.delete('/api/cards', authMiddleware, async (c) => { const u=c.get('user'); const {card_id}=await c.req.json(); if(!card_id) return c.json({error:'Card ID required'},400); await c.env.DB.prepare('UPDATE cards SET is_active=0 WHERE id=? AND user_id=?').bind(card_id,u.id).run(); return c.json({message:'Card removed'}); });
app.post('/api/account/freeze', authMiddleware, async (c) => { const u=c.get('user'); const {reason}=await c.req.json(); await c.env.DB.prepare("UPDATE users SET is_frozen=1,frozen_reason=?,frozen_at=datetime('now'),updated_at=datetime('now') WHERE id=?").bind(reason||'Self-frozen',u.id).run(); await audit(c.env,u.id,'account_freeze',getClientIP(c),{reason}); await c.env.DB.prepare('DELETE FROM sessions WHERE user_id=?').bind(u.id).run(); return c.json({message:'Account frozen. Logged out everywhere.'}); });
app.post('/api/account/unfreeze', async (c) => { const {email,verification_code}=await c.req.json(); if(!email||!verification_code) return c.json({error:'Email and code required'},400); const u=await c.env.DB.prepare('SELECT id FROM users WHERE email=? AND is_frozen=1').bind(email.toLowerCase()).first<any>(); if(!u) return c.json({error:'No frozen account'},404); const at=await c.env.DB.prepare("SELECT * FROM auth_tokens WHERE user_id=? AND type='email_verify' AND token=? AND used=0 AND expires_at>?").bind(u.id,verification_code,Date.now()).first<any>(); if(!at) return c.json({error:'Invalid code'},400); await c.env.DB.batch([c.env.DB.prepare("UPDATE users SET is_frozen=0,frozen_reason=NULL,frozen_at=NULL,updated_at=datetime('now') WHERE id=?").bind(u.id),c.env.DB.prepare('UPDATE auth_tokens SET used=1 WHERE id=?').bind(at.id)]); await audit(c.env,u.id,'account_unfreeze',getClientIP(c)); return c.json({message:'Account unfrozen'}); });
app.post('/api/account/unfreeze/request', async (c) => { const {email}=await c.req.json(); if(!email) return c.json({error:'Email required'},400); const u=await c.env.DB.prepare('SELECT id FROM users WHERE email=? AND is_frozen=1').bind(email.toLowerCase()).first<any>(); if(!u) return c.json({success:true,message:'If frozen account exists, code sent'}); const vt=generateToken(8); await c.env.DB.prepare("INSERT INTO auth_tokens (id,user_id,token,type,expires_at) VALUES (?,?,'email_verify',?)").bind(generateId('tok_'),u.id,Date.now()+3600000).run(); await sendEmail(c.env,email,'Unfreeze code',`<p>Code: <strong>${vt}</strong></p>`); return c.json({success:true,message:'If frozen account exists, code sent'}); });
app.post('/api/transactions/:id/reverse', authMiddleware, async (c) => { const u=c.get('user'); const ip=getClientIP(c); const txId=c.req.param('id'); const {pin,reason}=await c.req.json(); const pc=await verifyPinForTransaction(c.env,u.id,pin); if(!pc.valid) return c.json({error:pc.error},401); const tx=await c.env.DB.prepare("SELECT * FROM transactions WHERE id=? AND user_id=? AND type='p2p_send' AND status='success'").bind(txId,u.id).first<any>(); if(!tx) return c.json({error:'Not reversible'},404); const le=await c.env.DB.prepare("SELECT * FROM ledger_entries WHERE reference=? AND sender_id=? AND status='success'").bind(tx.reference,u.id).first<any>(); if(!le) return c.json({error:'Ledger not found'},404); const rid=le.recipient_id; const amt=le.amount; const fee=le.fee; const tr=amt+fee; const tc=le.currency; const rw=await getWalletBalance(c.env,rid,tc); if(!rw||rw.balance<amt) return c.json({error:'Recipient insufficient balance'},400); const sw=await getWalletBalance(c.env,u.id,tc); if(!sw) return c.json({error:'Your wallet not found'},400); const dr=await c.env.DB.prepare("UPDATE wallets SET balance=balance-?,updated_at=datetime('now') WHERE id=? AND balance>=?").bind(amt,rw.walletId,amt).run(); if(!dr.meta.changes||dr.meta.changes===0) return c.json({error:'Recipient insufficient for reversal'},409); await c.env.DB.batch([c.env.DB.prepare("UPDATE wallets SET balance=balance+?,updated_at=datetime('now') WHERE id=?").bind(tr,sw.walletId),c.env.DB.prepare("UPDATE transactions SET status='reversed',reversed_by=?,reversed_at=datetime('now'),updated_at=datetime('now') WHERE id=?").bind(u.id,tx.id),c.env.DB.prepare("UPDATE transactions SET status='reversed',reversed_by=?,reversed_at=datetime('now'),updated_at=datetime('now') WHERE reference=? AND type='p2p_receive'").bind(u.id,tx.reference),c.env.DB.prepare("UPDATE ledger_entries SET status='reversed' WHERE reference=?").bind(tx.reference),c.env.DB.prepare("INSERT INTO transactions (id,user_id,type,channel,amount,fee,currency,status,reference,description,recipient_name,pin_verified) VALUES (?,?,'reversal','system',?,0.0,?,'success',?,'P2P reversed',?,1)").bind(generateId('tx_'),u.id,amt,tc,`REV-${tx.reference}`,`@${rid}`),c.env.DB.prepare("INSERT INTO transactions (id,user_id,type,channel,amount,fee,currency,status,reference,description,recipient_name,pin_verified) VALUES (?,?,'reversal','system',?,0.0,?,'success',?,'P2P reversed (debited)',?,0)").bind(generateId('tx_'),rid,amt,tc,`REV-${tx.reference}`,`@${u.username||u.email}`)]); await createNotification(c.env,u.id,'reversal','Transfer Reversed',`P2P of ${amt.toFixed(2)} ${tc} reversed. ${tr.toFixed(2)} refunded. Ref: ${tx.reference}`,tx.reference,amt,tc); const ru=await getUserById(c.env,rid); if(ru) { await createNotification(c.env,rid,'reversal','Transfer Reversed',`P2P of ${amt.toFixed(2)} ${tc} from @${u.username||u.email} reversed. ${amt.toFixed(2)} debited.`,tx.reference,amt,tc); await sendEmail(c.env,ru.email,'Transfer reversed',`<h2>Reversed</h2><p>Amount: ${amt.toFixed(2)} ${tc}</p>`); } await audit(c.env,u.id,'transaction_reversal',ip,{txId,reference:tx.reference,amount:amt,recipient:rid,reason}); const nb=await getWalletBalance(c.env,u.id,tc); return c.json({message:'Reversed',reference:tx.reference,reversed_amount:amt,fee_refunded:fee,currency:tc,new_balance:nb?.balance??0,status:'reversed'}); });
app.get('/api/notifications', authMiddleware, async (c) => { const u=c.get('user'); const l=Math.min(parseInt(c.req.query('limit')||'20'),100); const o=parseInt(c.req.query('offset')||'0'); const un=c.req.query('unread')==='true'; const q=un?'SELECT * FROM notifications WHERE user_id=? AND is_read=0 ORDER BY created_at DESC LIMIT ? OFFSET ?':'SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT ? OFFSET ?'; const r=await c.env.DB.prepare(q).bind(u.id,l,o).all(); const uc=await c.env.DB.prepare('SELECT COUNT(*) as count FROM notifications WHERE user_id=? AND is_read=0').bind(u.id).first<any>(); return c.json({notifications:r.results||[],unread_count:uc?.count||0}); });
